-- Fictional film-studio universe. Generated by gen-seed.js (not shipped).
PRAGMA foreign_keys = ON;

CREATE TABLE studios (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  founded INTEGER,
  country TEXT
);
CREATE TABLE films (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  year INTEGER,
  runtime_min INTEGER,
  budget_musd REAL,
  gross_musd REAL,
  studio_id INTEGER REFERENCES studios(id)
);
CREATE TABLE people (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  born INTEGER,
  nationality TEXT
);
CREATE TABLE credits (
  film_id INTEGER NOT NULL REFERENCES films(id),
  person_id INTEGER NOT NULL REFERENCES people(id),
  role TEXT NOT NULL CHECK (role IN ('director','writer','actor','composer','producer')),
  character TEXT,
  PRIMARY KEY (film_id, person_id, role)
);
CREATE TABLE genres (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);
CREATE TABLE film_genres (
  film_id INTEGER NOT NULL REFERENCES films(id),
  genre_id INTEGER NOT NULL REFERENCES genres(id),
  PRIMARY KEY (film_id, genre_id)
);
CREATE TABLE awards (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL
);
CREATE TABLE nominations (
  id INTEGER PRIMARY KEY,
  award_id INTEGER NOT NULL REFERENCES awards(id),
  film_id INTEGER NOT NULL REFERENCES films(id),
  person_id INTEGER REFERENCES people(id),
  year INTEGER NOT NULL,
  won INTEGER NOT NULL DEFAULT 0
);








